select md5(prosrc)='f8a5ac30094b81d9f46e00f6e6d8f842' as body_matches, proacl::text='{postgres=X/postgres,=X/postgres}' as acl_preserved, prosecdef and proconfig=array['search_path=public, pg_temp'] as security_preserved from pg_proc where oid='public.fn_cancel_booking(text,text,boolean)'::regprocedure;
select md5(prosrc)='43efe9d94f06fb70171fcb7a7fc4b6d5' as sibling_guard_matches, not has_function_privilege('anon',oid,'execute') and not has_function_privilege('authenticated',oid,'execute') and not has_function_privilege('service_role',oid,'execute') as guard_internal_only, exists(select 1 from pg_trigger where tgrelid='public.bookings'::regclass and tgname='trg_treadmill_sibling_parent_guard' and tgenabled='O' and tgtype=23) as trigger_enabled from pg_proc where oid=to_regprocedure('public.fn_treadmill_sibling_parent_guard()');
